from forecast_common import *
def main():
 OUT.mkdir(parents=True,exist_ok=True)
 cfg=dict(version=OUT.name,base='Saved translation_forecast_20261020 with_translation matching fold/seed checkpoints; preserve all original weights and predictions.',arms=ARMS,seeds=[17,29,43],architecture='Unmodified original separated camera GRU6->32 and person GRU9->64,context,future/history flow heads. Rotation-only compensation/reprojection, historical translation features. No added patch/depth input.',training='Freeze saved camera weights. Fine-tune all person weights from same saved initialization per fold/seed,240updates,batch48,AdamW lr.0001 wd.01,clip1. No augmentation in either arm; original future-flow+.5history-flow loss,5inference draws10steps. Validation original residual ADE every20steps with step0 eligible. RNG schedule shared, datasets/record groups differ so actual sampled windows differ.',datasets='Primary trimmed arm:412 quality-trimmed21point windows only, from17segments; original_data control:original117 only. No union or replacing old labels. Overlaps inventoried; highly overlapping windows not independent observations.',splits='Original6 recording-held-out folds. For each fit, trimmed rows from BOTH validation and test recordings excluded. Unchanged old validation/test arrays and117 test windows. New rows from heldout recordings never used for adaptation or model selection.',horizon='16past1.5s ->5future.5s. Training samples reconstructed from exact candidate centers+originalRGB calibration/orientation, prior-verified RGB optical-center MPS positions. Translation computed ONLY over historical16points.',selection='All training settings locked before scoring; no test tuning. Compare saved baseline,original-data continuation,trimmed-data continuation,hold-last on exact same test cases. Report residual and fixed camera angle,recording/seed/sparse summaries and original9cases.',limits='Offline quality selection can use whole segments; never feeds future observations into prediction. Offline MPS/SAM references not online causal pipeline or independent dense GT. Data composition,size,stride and retention differ; no pure label-quality causal claim. The latest local-appearance output is NOT used.')
 if (OUT/'protocol.json').exists():assert read(OUT/'protocol.json')==cfg
 else:write(OUT/'protocol.json',cfg);write(ROOT/'plans/TRIMMED_FORECAST_FINETUNE_20261028.txt',cfg)
 inv=read(ASSOC/'inventory.json');windows=read(TRIM/'forecast_window_candidates.json')['windows'];assert len(windows)==412;segments={s['segment_id']:s for s in read(TRIM/'retained_segments.json')};entries={(e['clip'],e['frame']):e for e in inv['entries']};lookup={t['target_key']:(e,t) for e in inv['entries'] for t in e['targets']};old=dict(np.load(BASE/'dataset.npz'));oldmeta=read(BASE/'samples.json');folds=read(BASE/'folds.json');refs={};poses={};rows=[];meta=[];overlap=[];rotmax=0.;transmax=0.
 protected={}
 for folder in [BASE,TRIM]:
  for p in folder.rglob('*'):
   if p.is_file() and p.suffix in ['.pt','.npz','.json'] and 'presentation' not in p.parts:protected[str(p.relative_to(ROOT))]=sha(p)
 for folder in ['translation_forecast_20261020','horizon_swap_20261017','biflow_aria_v1_20261002','track_trimming_20261028']:
  for p in (ROOT/'scripts'/folder).glob('*.py'):protected[str(p.relative_to(ROOT))]=sha(p)
 for j,w in enumerate(windows):
  s=segments[w['segment_id']];cid=s['clip'];fs=np.arange(w['start'],w['end']+1);assert len(fs)==21 and w['cutoff']==fs[15]
  if cid not in refs:
   rp=ROOT/entries[cid,0]['input']/'reference.npz';pp=ASSOC/'poses'/f'{cid}.npz';refs[cid]=dict(np.load(rp));poses[cid]=dict(np.load(pp));protected[str(rp.relative_to(ROOT))]=sha(rp);protected[str(pp.relative_to(ROOT))]=sha(pp)
  ref=refs[cid];p=poses[cid];rr=[lookup[u] for u in w['uids']];assert all(e['clip']==cid and e['frame']==f for (e,t),f in zip(rr,fs));boxes=np.array([t['box'] for e,t in rr],float);xy=(boxes[:,:2]+boxes[:,2:])/2;R=ref['R'][fs];K=ref['K'];ts=ref['times_ns'][fs];rel=np.einsum('ji,tjk->tik',R[15],R);H=np.einsum('ij,tjk,kl->til',K,rel,np.linalg.inv(K));translation=np.einsum('ji,tj->ti',R[15],p['c'][fs[:16]]-p['c'][fs[15]]).astype(np.float32);pos=p['c'][fs[:16]]+p['world_origin'];assert (p['selected_mps_ns'][fs[:16]]<=ts[:16]).all();assert np.array_equal(ts,p['times_ns'][fs]);rotmax=max(rotmax,float(abs(p['R'][fs]-R).max()))
  rows.append(dict(xy=xy,raw=xy.copy(),raw_valid=np.ones(21,np.float32),R=R,K=K,H=H,cam=rv(rel),seconds=(ts-ts[15])/1e9,boxes=boxes,translation=translation,translation_mps_ns=p['selected_mps_ns'][fs[:16]],translation_world_position=pos))
  mm=dict(key=f'trim_{cid}_T{s["original_track_id"]}_{fs[0]:03d}',clip=cid,id=f'T{s["original_track_id"]}',segment=s['segment_id'],recording=rr[0][0]['recording'],frames=fs.tolist(),cutoff=int(fs[15]),timestamp_ns=int(ts[15]),timestamps_ns=ts.tolist(),nonoverlap=bool((fs[0]-s['start'])%21==0),uids=w['uids']);meta.append(mm)
  for oi,om in enumerate(oldmeta):
   if om['clip']==cid and om['frames']==fs.tolist() and np.array_equal(old['xy'][oi],xy):
    td=float(abs(old['translation'][oi]-translation).max());transmax=max(transmax,td);assert td<1e-6;assert np.max(abs(old['H'][oi]-H))<1e-8;overlap.append(dict(new_index=j,old_index=oi,translation_max_difference_m=td))
 data={k:np.stack([r[k] for r in rows]) for k in rows[0]};assert np.isfinite(data['translation']).all();assert (data['translation'][:,-1]==0).all();assert len({(m['recording'],tuple(m['uids'])) for m in meta})==len(meta)
 _,z=warp(data['xy'],data['H']);assert (z>1e-6).all();plan=[]
 for f in folds:
  idx=[i for i,m in enumerate(meta) if m['recording'] not in [f['test'],f['validation']]];assert idx;assert {meta[i]['recording'] for i in idx}<=set(f['train']);plan.append(dict(fold=f['fold'],test=f['test'],validation=f['validation'],trimmed_train_indices=idx,trimmed_train_recordings=sorted({meta[i]['recording'] for i in idx}),trimmed_train_count=len(idx),original_train_count=len(f['train_indices']),heldout_trimmed_unused=len(meta)-len(idx)))
 np.savez_compressed(OUT/'trimmed_dataset.npz',**data);write(OUT/'trimmed_samples.json',meta);write(OUT/'fold_plan.json',plan);write(OUT/'folds.json',folds);write(OUT/'source_hashes.json',protected);write(OUT/'overlap_with_original.json',overlap);write(OUT/'preflight.json',dict(passed=True,trimmed_windows=len(meta),segments=len(segments),recordings=len({m['recording'] for m in meta}),exact_original_windows=len(overlap),max_overlap_translation_difference_m=transmax,max_raw_vs_original_reference_rotation_element_difference=rotmax,source_hashes=len(protected),per_recording={g:sum(m['recording']==g for m in meta) for g in sorted({m['recording'] for m in meta})},fold_training_counts=[{k:v for k,v in p.items() if k!='trimmed_train_indices'} for p in plan]));print(read(OUT/'preflight.json'))
if __name__=='__main__':main()
